360.           <p class="intro">Pick a single notification channel for account alerts and product updates.</p>
361.           <form id="preferences-form" novalidate>
362.             <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required field</p>
363.             ${NotificationQuestion()}
364.             <div class="submit-row">
365.               <button type="submit">Save preferences</button>
366.             </div>
367.             <p id="form-status" class="form-status" aria-live="polite"></p>
