               ${notificationOptions.map(RadioOption).join("")}
             </div>
             <p id="notification-error" class="field-error" role="alert" hidden></p>
           </fieldset>
         </div>
       `;
     }

     function NotificationForm() {
       return `
         <section class="form-card" aria-labelledby="page-title">
           <p class="eyebrow">Preference center</p>
           <h1 id="page-title">Stay in sync with the updates you want.</h1>
           <p class="intro">Pick a single notification channel for account alerts and product updates.</p>
           <form id="preferences-form" novalidate>
             <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required field</p>
             ${NotificationQuestion()}
             <div class="submit-row">
               <button type="submit">Save preferences</button>
             </div>
             <p id="form-status" class="form-status" aria-live="polite"></p>
           </form>
         </section>
       `;
     }

     function App() {
       return PageShell(NotificationForm());
     }

     function setGroupValidity(hasError) {
       document
         .querySelectorAll('input[name="notificationPreference"]')
         .forEach((radio) => {
           if (hasError) {
             radio.setAttribute("aria-invalid", "true");
           } else {
             radio.removeAttribute("aria-invalid");
           }
         });
     }

     function clearFeedback() {
       const error = document.getElementById("notification-error");
       const status = document.getElementById("form-status");

       error.hidden = true;
       error.textContent = "";
       status.textContent = "";
       status.dataset.state = "";
       setGroupValidity(false);
     }

     function showError(message) {
       const error = document.getElementById("notification-error");
       const firstRadio = document.querySelector('input[name="notificationPreference"]');

       error.hidden = false;
       error.textContent = message;
       setGroupValidity(true);
       firstRadio.focus();
     }

     function showSuccess(message) {
       const status = document.getElementById("form-status");

       status.dataset.state = "success";
       status.textContent = message;
     }

     function attachFormBehavior() {
       const form = document.getElementById("preferences-form");
       const radios = document.querySelectorAll('input[name="notificationPreference"]');

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const selected = document.querySelector('input[name="notificationPreference"]:checked');

         clearFeedback();

         if (!selected) {
           showError("Error: Choose how you prefer to receive notifications.");
           return;
         }

         showSuccess(`Preference saved: ${selected.value}.`);
       });

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           clearFeedback();
         });
       });
     }

     document.getElementById("app").innerHTML = App();
     attachFormBehavior();
   </script>
 </body>
 </html>

')
